// A header fixture: 1.x blocks beside a 2.0 declaration. Only the 1.x ones change; the 2.0 one is reprinted.
// This comment block stays where it is.

float Twice(float x)
{
    return x * 2.0;
}

/// @custom
void Remap01(float value, out float result)
{
    // hlsl, verbatim
    result = saturate(value * 0.5 + 0.5);
}

/// @custom
/// @name Common::ApplyTint
void Common_ApplyTint(float3 color, float3 tint, out float3 result)
{
    result = lerp(color, color * tint, 1.0);
}

// A lifted call in a 1.x spelling, two lines below the block's indentation.
/// @custom
/// @name Common::TexelSize
void Common_TexelSize(float scale, out float2 result)
{
    float2 inv = UE.SceneTexture(SceneTextureId = "SceneColor").InvSize;
    result = inv * scale;
}

/// @custom
void WindPulse(float2 uv, out float pulse)
{
    float t = UE.Time();
    pulse = sin(uv.x * 8.0 + t);
}
